using UnityEngine;

namespace Astrea;

public class CustomBattleActionDescriptionSpecifics : ScriptableObject
{
	protected int GetFinalAmountWithoutEquation(string modifiedAmount)
	{
		if (modifiedAmount.Contains("("))
		{
			return int.Parse(modifiedAmount.Split('(').First());
		}
		return int.Parse(modifiedAmount);
	}

	protected int GetAmountWithoutEquation(string modifiedAmount)
	{
		if (modifiedAmount.Contains("("))
		{
			int num = modifiedAmount.IndexOf('(');
			int num2 = modifiedAmount.IndexOf('+');
			return int.Parse(modifiedAmount.Substring(num + 1, num2 - num - 1));
		}
		return int.Parse(modifiedAmount);
	}

	protected int GetBonusAmountWithoutEquation(string modifiedAmount)
	{
		int result = 0;
		if (modifiedAmount.Contains("("))
		{
			int num = modifiedAmount.IndexOf('+');
			int num2 = modifiedAmount.IndexOf(')');
			result = int.Parse(modifiedAmount.Substring(num + 1, num2 - num - 1));
		}
		return result;
	}
}
